import java.util.Scanner;

public class Main {
    static int[] parentNodes;
    static int countComponents;
    static final long MOD = 1000000007;

    static int findParent(int x) {
        if (parentNodes[x] == x) return x;
        parentNodes[x] = findParent(parentNodes[x]);
        return parentNodes[x];
    }

    static void unionSets(int a, int b) {
        a = findParent(a);
        b = findParent(b);
        if (a == b) return;
        countComponents--;
        parentNodes[b] = a;
    }

    static long modExp(long base, int exp) {
        if (exp == 0) return 1;
        long half = modExp(base, exp / 2);
        long res = (half * half) % MOD;
        if ((exp & 1) == 1) res = (res * base) % MOD;
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();

        if (k == 0) {
            System.out.println(modExp(p, (int)(p - 1)));
            sc.close();
            return;
        }

        parentNodes = new int[(int)p];
        countComponents = (int)(p - (k > 1 ? 1 : 0));
        for (int i = 1; i < p; i++) {
            parentNodes[i] = i;
        }

        for (int i = 1; i < p; i++) {
            unionSets(i, (int)((i * k) % p));
        }

        System.out.println(modExp(p, countComponents));
        sc.close();
    }
}
